    variables[`--ui-type-${role}-line-height`] = String(style.lineHeight);
    variables[`--ui-type-${role}-weight`] = String(style.weight);
    variables[`--ui-type-${role}-letter-spacing`] = `${style.letterSpacing}em`;
  }
